package com.example.code.ui

import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.rememberScrollState
import androidx.compose.foundation.verticalScroll
import androidx.compose.material3.MaterialTheme
import androidx.compose.runtime.collectAsState
import androidx.compose.runtime.getValue
import androidx.compose.ui.Modifier
import androidx.compose.ui.test.assertIsDisplayed
import androidx.compose.ui.test.assertIsEnabled
import androidx.compose.ui.test.assertIsNotEnabled
import androidx.compose.ui.test.assertIsSelected
import androidx.compose.ui.test.junit4.createComposeRule
import androidx.compose.ui.test.onNodeWithTag
import androidx.compose.ui.test.onNodeWithText
import androidx.compose.ui.test.performClick
import androidx.compose.ui.test.performScrollTo
import androidx.test.ext.junit.runners.AndroidJUnit4
import com.example.code.data.CampsiteRatingStore
import com.example.code.model.Campsite
import com.example.code.model.Rating
import com.example.code.model.Reservation
import com.example.code.model.averageRating
import com.example.code.ui.entrant.CampsiteDetailsScreen
import com.example.code.ui.entrant.CampsiteRatings
import com.example.code.ui.entrant.CampsiteRatingsScreen
import com.example.code.ui.entrant.campsiteRatingText
import kotlinx.coroutines.CompletableDeferred
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.flow
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Rule
import org.junit.Test
import org.junit.runner.RunWith

@RunWith(AndroidJUnit4::class)
class CampsiteRatingIntentTest {
    @get:Rule val compose = createComposeRule()
    private val now = 10_000L
    private val stay = Reservation(
        id = "jasper-stay-1", campsiteId = "jasper", campsiteName = "Jasper Riverside",
        entrantId = "priya", startDate = 100, endDate = 200,
    )

    @Test fun entrantChoosesAScoreAndSeesTheSavedOverallRating() {
        val store = Ratings()
        compose.setContent {
            val ratings by store.rows.collectAsState()
            MaterialTheme {
                CampsiteDetailsScreen(
                    Campsite(id = "jasper", name = "Jasper Riverside", rating = averageRating(ratings)),
                    onBack = {},
                ) {
                    CampsiteRatings("jasper", "priya", listOf(stay), store) { now }
                }
            }
        }
        compose.onNodeWithTag("saveStayRating-${stay.id}").performScrollTo().assertIsNotEnabled()
        choose(stay.id, 4)
        save(stay.id)
        compose.onNodeWithText("Rating saved.").performScrollTo().assertIsDisplayed()
        compose.onNodeWithText(campsiteRatingText(4.0)).performScrollTo().assertIsDisplayed()
        compose.runOnIdle {
            assertEquals(1, store.rows.value.size)
            assertEquals(stay.id, store.rows.value.single().reservationId)
        }
    }

    @Test fun ratingTheSameStayAgainUpdatesInsteadOfDuplicating() {
        val store = Ratings(listOf(Rating(stay.id, "priya", "jasper", 2, stay.id)))
        show(store)
        compose.onNodeWithTag("stayRatingScore-${stay.id}-2").assertIsSelected()
        compose.onNodeWithText("Update rating").assertIsNotEnabled()
        choose(stay.id, 5)
        save(stay.id)
        compose.onNodeWithText("Rating updated.").assertIsDisplayed()
        compose.onNodeWithText("Your rating: 5 / 5").assertIsDisplayed()
        compose.runOnIdle {
            assertEquals(1, store.rows.value.size)
            assertEquals(5, store.rows.value.single().score)
        }
    }

    @Test fun twoCompletedStaysHaveIndependentRatingControls() {
        val store = Ratings()
        val second = stay.copy(id = "jasper-stay-2", startDate = 300, endDate = 400)
        show(store, listOf(stay, second))
        choose(stay.id, 5)
        save(stay.id)
        choose(second.id, 1)
        save(second.id)
        compose.runOnIdle {
            assertEquals(2, store.rows.value.size)
            assertEquals(3.0, averageRating(store.rows.value)!!, 0.0)
        }
    }

    @Test fun entrantWithoutAPastStayCannotSubmitARating() {
        val store = Ratings()
        show(store, listOf(
            stay.copy(id = "future", endDate = now + 100),
            stay.copy(id = "cancelled", status = Reservation.STATUS_CANCELLED),
            stay.copy(id = "other-entrant", entrantId = "liam"),
        ))
        compose.onNodeWithText("You can rate this campsite after a completed stay.").assertIsDisplayed()
        compose.onNodeWithText("Submit rating").assertDoesNotExist()
        compose.runOnIdle { assertEquals(0, store.writes) }
    }

    @Test fun failedSaveKeepsTheChoiceAndAllowsRetry() {
        val store = Ratings().apply { failWrites = true }
        show(store)
        choose(stay.id, 3)
        save(stay.id)
        compose.onNodeWithText("Could not save your rating. Please try again.").assertIsDisplayed()
        compose.onNodeWithTag("stayRatingScore-${stay.id}-3").assertIsSelected()
        compose.onNodeWithTag("saveStayRating-${stay.id}").assertIsEnabled()
        compose.runOnIdle {
            assertTrue(store.rows.value.isEmpty())
            store.failWrites = false
        }
        save(stay.id)
        compose.onNodeWithText("Rating saved.").assertIsDisplayed()
    }

    @Test fun failedLoadOffersRetryRatherThanAllowingAnUnloadedScoreToBeOverwritten() {
        val store = Ratings().apply { failReads = true }
        show(store)
        compose.onNodeWithText("Could not load your ratings.").assertIsDisplayed()
        compose.onNodeWithText("Submit rating").assertDoesNotExist()
        compose.runOnIdle { store.failReads = false }
        compose.onNodeWithTag("retryStayRatings").performClick()
        compose.onNodeWithText("Submit rating").assertIsDisplayed()
    }

    @Test fun pendingSaveDisablesAnotherSubmission() {
        val store = Ratings().apply { gate = CompletableDeferred() }
        show(store)
        choose(stay.id, 5)
        save(stay.id)
        compose.onNodeWithTag("saveStayRating-${stay.id}").assertIsNotEnabled()
        compose.onNodeWithTag("stayRatingScore-${stay.id}-1").assertIsNotEnabled()
        compose.onNodeWithText("Saving rating…").assertIsDisplayed()
        compose.runOnIdle { store.gate!!.complete(Unit) }
        compose.onNodeWithText("Rating saved.").assertIsDisplayed()
    }

    @Test fun loadingDoesNotExposeSubmissionControls() {
        compose.setContent {
            MaterialTheme { CampsiteRatingsScreen(listOf(stay), emptyList(), loading = true, onSubmit = { _, _ -> }) }
        }
        compose.onNodeWithText("Loading your ratings…").assertIsDisplayed()
        compose.onNodeWithText("Submit rating").assertDoesNotExist()
    }

    private fun show(store: Ratings, stays: List<Reservation> = listOf(stay)) {
        compose.setContent {
            MaterialTheme {
                Column(Modifier.verticalScroll(rememberScrollState())) {
                    CampsiteRatings("jasper", "priya", stays, store) { now }
                }
            }
        }
    }

    private fun choose(id: String, score: Int) {
        compose.onNodeWithTag("stayRatingScore-$id-$score").performScrollTo().performClick()
    }

    private fun save(id: String) {
        compose.onNodeWithTag("saveStayRating-$id").performScrollTo().performClick()
    }

    private class Ratings(initial: List<Rating> = emptyList()) : CampsiteRatingStore {
        val rows = MutableStateFlow(initial)
        var writes = 0
        var failWrites = false
        var failReads = false
        var gate: CompletableDeferred<Unit>? = null

        override fun observeRatings(campsiteId: String, entrantId: String): Flow<List<Rating>> = flow {
            check(!failReads) { "Offline" }
            rows.collect { list -> emit(list.filter { it.campsiteId == campsiteId && it.entrantId == entrantId }) }
        }

        override suspend fun saveRating(campsiteId: String, reservationId: String, entrantId: String, score: Int) {
            gate?.await()
            check(!failWrites) { "Offline" }
            writes++
            rows.value = rows.value.filterNot { it.id == reservationId } +
                    Rating(reservationId, entrantId, campsiteId, score, reservationId)
        }
    }
}
